const fs = require('fs');

function findCenter(n, edges) {
  const deg = new Int32Array(n + 2);
  for (let i = 0; i < edges.length; i += 2) {
    deg[edges[i]]++;
    deg[edges[i + 1]]++;
  }
  const start = new Int32Array(n + 2);
  for (let v = 1; v <= n; v++) start[v + 1] = start[v] + deg[v];
  const adj = new Int32Array(edges.length);
  const pos = start.slice();
  for (let i = 0; i < edges.length; i += 2) {
    const a = edges[i], b = edges[i + 1];
    adj[pos[a]++] = b;
    adj[pos[b]++] = a;
  }
  const dist = new Int32Array(n + 1);
  const parent = new Int32Array(n + 1);
  const queue = new Int32Array(n);

  function bfs(src) {
    dist.fill(-1);
    let qh = 0, qt = 0, far = src;
    queue[qt++] = src;
    dist[src] = 0;
    while (qh < qt) {
      const u = queue[qh++];
      const du = dist[u];
      for (let p = start[u]; p < start[u + 1]; p++) {
        const v = adj[p];
        if (dist[v] === -1) {
          dist[v] = du + 1;
          parent[v] = u;
          if (dist[v] > dist[far]) far = v;
          queue[qt++] = v;
        }
      }
    }
    return far;
  }

  // Diâmetro via dupla BFS
  const e1 = bfs(1);
  const e2 = bfs(e1);
  const L = dist[e2]; // diâmetro em número de arestas
  // Centro: vértice a floor(L/2) arestas de uma extremidade do caminho do diâmetro
  let steps = L >> 1;
  let c = e2;
  while (steps-- > 0) c = parent[c];
  return c;
}

function main() {
  const data = fs.readFileSync(0, 'utf8').split(/\s+/).filter(s => s.length).map(Number);
  let idx = 0;
  const N = data[idx++];
  const M = data[idx++];
  const edges1 = data.slice(idx, idx + 2 * (N - 1));
  idx += 2 * (N - 1);
  const edges2 = data.slice(idx, idx + 2 * (M - 1));

  const c1 = findCenter(N, edges1);
  const c2 = findCenter(M, edges2);
  process.stdout.write(c1 + ' ' + c2 + '\n');
}

main();
